def transform(g):
    h,w=len(g),len(g[0])
    blue=red=None
    for r in range(h):
        for c in range(w):
            if g[r][c]==1: blue=(r,c)
            if g[r][c]==2: red=(r,c)
    o=[row[:] for row in g]
    rb,cb=blue; rr,cr=red
    rs=-1 if rr<rb else 1
    cs=1 if cr>cb else -1
    r=rb+rs
    while r!=rr:
        o[r][cb+cs*(r-rb)*abs(cs)]=3
        r+=rs
    # horizontal fill on row rr-rs from last diag col+cs to cr-cs
    hr=rr-rs
    lc=cb+cs*(hr-rb)
    c=lc+cs
    while (c-cr)*cs<0:
        o[hr][c]=3
        c+=cs
    return o
